# frozen_string_literal: true

module Anthropic
  module Models
    # The file has `downloadable: false`. Only files generated by a tool, such as the
    # code execution tool, can be downloaded.
    class FileNotDownloadableError < Anthropic::Errors::BadRequestError
      # @!method error_code
      #   @return [Symbol, :file_not_downloadable]

      # @return [Anthropic::Models::FileNotDownloadableErrorDetails]
      def details
        Anthropic::Internal::Type::Converter.coerce(
          Anthropic::FileNotDownloadableErrorDetails,
          Anthropic::Internal::Util.dig(body, [:error, :details])
        )
      end
    end
  end
end
